begin;
do $$
declare owner_id uuid:=gen_random_uuid(); operator_id uuid:=gen_random_uuid(); other_id uuid:=gen_random_uuid(); sid uuid; result jsonb;
 code text:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
begin
 insert into auth.users(id,email) values(owner_id,owner_id||'@example.invalid'),(operator_id,operator_id||'@example.invalid'),(other_id,other_id||'@example.invalid');
 insert into public.game_sessions(join_code,controller_id,state) values(code,owner_id,'{"operationName":"Teste bombas","bombSequence":[{"id":"b1","name":"Alpha"},{"id":"b2","name":"Bravo"}]}') returning id into sid;
 insert into public.game_members(session_id,user_id,device_id,role) values(sid,operator_id,'artifact-test-a','artifact'),(sid,operator_id,'artifact-test-b','artifact'),(sid,other_id,'player-test','player');
 perform set_config('request.jwt.claim.sub',other_id::text,true);
 begin perform public.register_bomb_device(sid,'d1','player-test','Tablet teste','tablet');raise exception 'FAIL jogador cadastrou bomba';exception when others then if sqlerrm not like 'Entre como Bomba%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 result:=public.register_bomb_device(sid,'d1','artifact-test-a','Tablet teste','tablet');
 if result->'state'->'bombDevices'->0->>'status'<>'pending' then raise exception 'FAIL cadastro pendente';end if;
 perform public.register_bomb_device(sid,'d2','artifact-test-b','Notebook teste','notebook');
 begin perform public.assign_bomb_device(sid,'d1','b1');
 if (select status from public.game_members where session_id=sid and device_id='artifact-test-a')<>'approved' then raise exception 'FAIL aceite do membro';end if;raise exception 'FAIL aparelho se aprovou';exception when others then if sqlerrm not like 'Somente o Controle%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 begin perform public.assign_bomb_device(sid,'d1','inexistente');raise exception 'FAIL bomba inválida';exception when others then if sqlerrm not like 'Escolha uma bomba%' then raise;end if;end;
 perform public.assign_bomb_device(sid,'d1','b1');
 if (select status from public.game_members where session_id=sid and device_id='artifact-test-a')<>'approved' then raise exception 'FAIL aceite do membro';end if;
 begin perform public.assign_bomb_device(sid,'d2','b1');raise exception 'FAIL vínculo duplicado';exception when others then if sqlerrm not like 'Esta bomba já%' then raise;end if;end;
 update public.game_sessions set state=jsonb_set(state,'{bombDevices}','[]') where id=sid;
 if (select jsonb_array_length(state->'bombDevices') from public.game_sessions where id=sid)<>2 then raise exception 'FAIL estado antigo apagou cadastros';end if;
 perform public.assign_bomb_device(sid,'d2','b2');
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 result:=public.register_bomb_device(sid,'d1','artifact-test-a','Tablet atualizado','tablet');
 if not exists(select 1 from public.game_bomb_devices where session_id=sid and id='d1' and status='approved' and bomb_id='b1') then raise exception 'FAIL reenviar apagou aprovação';end if;
 update public.game_sessions set status='running' where id=sid;
 begin perform public.register_bomb_device(sid,'d1','artifact-test-a','Tablet atualizado','tablet');raise exception 'FAIL cadastro em partida ativa';exception when others then if sqlerrm not like 'Cadastre o dispositivo%' then raise;end if;end;
 perform public.touch_bomb_device(sid,'d1','artifact-test-a');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 begin perform public.assign_bomb_device(sid,'d1','b2');raise exception 'FAIL troca em partida ativa';exception when others then if sqlerrm not like 'Organize os dispositivos%' then raise;end if;end;
 update public.game_sessions set status='setup' where id=sid;
 perform public.assign_bomb_device(sid,'d1',null,true);
 if (select jsonb_array_length(state->'bombDevices') from public.game_sessions where id=sid)<>1 then raise exception 'FAIL remoção do vínculo';end if;
 insert into public.game_bomb_devices(session_id,id,name,type,status,bomb_id) values(sid,'legacy','Aparelho existente','tablet','approved','b1');
 update public.game_sessions set status='running',state=state where id=sid;
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 perform public.register_bomb_device(sid,'legacy','artifact-test-a','Aparelho existente','tablet');
 if not exists(select 1 from public.game_bomb_devices where session_id=sid and id='legacy' and user_id=operator_id and status='approved') then raise exception 'FAIL migração do aparelho em jogo';end if;
end; $$;
rollback;
select 'PASS: cadastro antes do início, permissão do Controle, bomba válida, vínculo único, preservação em estado antigo, reenviar sem perder aprovação, presença, bloqueio durante partida e remoção. Dados de teste revertidos.' as resultado;
